document.addEventListener('DOMContentLoaded', () => {
    const tableBody = document.querySelector('.wise-table__body');
    const paginationContainer = '#pagination-area';

    // Grab all the rows generated by the JSP <c:forEach> loop
    // We convert the NodeList to an Array so PaginationHelper can slice it
    let allRows = Array.from(tableBody.querySelectorAll('.wise-table__row'));

    // If there are no entities, exit early
    if (allRows.length === 0) {
        const containerEl = document.querySelector(paginationContainer);
        if (containerEl) containerEl.classList.add('hidden');
        return;
    }

    /**
     * Renders a specific page of entities
     */
    function renderEntitiesPage(pageNumber) {
        // Clear the current table body
        tableBody.innerHTML = '';

        // Get the specific 10 rows for this page using your existing helper
        const rowsToDisplay = PaginationHelper.getPaginatedData(allRows, pageNumber);

        // Append the sliced rows back into the table body
        rowsToDisplay.forEach(row => {
            tableBody.appendChild(row);
        });

        // Render the page buttons
        PaginationHelper.renderPages(pageNumber, allRows.length, paginationContainer);
    }

    // Click listener to the pagination area
    document.querySelector(paginationContainer).addEventListener('click', (event) => {
        // Your helper will extract the page number and call renderEntitiesPage
        PaginationHelper.handlePageClick(event, renderEntitiesPage);
    });

    // Initialize the first page on load
    renderEntitiesPage(1);
});